// Test-entry dispatcher only. Original test bodies are separately compiled.
#include <string_view>
int surface_heat_public_main(int, char **);
int visibility_quality_main(int, char **);
int main(int argc, char **argv) {
  if (argc < 2) return 2;
  if (std::string_view(argv[1]) == "public")
    return surface_heat_public_main(argc - 1, argv + 1);
  if (std::string_view(argv[1]) == "quality")
    return visibility_quality_main(argc - 1, argv + 1);
  return 2;
}

